args.ReplacementContent:
{dayShifts.length > 0 ? (
  <>
    <div className="flex flex-col gap-1.5">
      {dayShifts.map(shift => renderShiftCard(shift))}
    </div>
    <div className="flex gap-1 mt-1.5 w-full">
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          handleCellClick(day.dateStr, 'openshifts', 'SERVER');
        }}
        className="flex-1 py-1 flex items-center justify-center gap-0.5 text-[8.5px] font-extrabold text-white/35 hover:text-white/80 bg-white/[0.02] hover:bg-white/[0.05] border border-dashed border-white/20 hover:border-white/40 rounded transition-all cursor-pointer border-solid"
      >
        <svg width="7" height="7" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
        ADD
      </button>
      <button
        type="button"
        data-group-popover-cell={day.dateStr}
        onClick={(e) => {
          e.stopPropagation();
          setCellGroupPopover(prev => prev === day.dateStr ? null : day.dateStr);
        }}
        className="flex-1 py-1 flex items-center justify-center gap-0.5 text-[8.5px] font-extrabold text-white/35 hover:text-white/80 bg-white/[0.02] hover:bg-white/[0.05] border border-dashed border-white/20 hover:border-white/40 rounded transition-all cursor-pointer relative border-solid"
      >
        <svg width="7" height="7" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
        GROUP

        {cellGroupPopover === day.dateStr && (
          <div 
            className="absolute top-full left-0 right-0 mt-1 bg-[#18181b] border border-white/10 rounded-lg shadow-xl z-30 p-1 flex flex-col gap-1 min-w-[130px]"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="text-[7.5px] font-extrabold text-white/40 uppercase tracking-widest px-1.5 py-0.5 border-b border-white/5">Select Saved Group</div>
            {crewGroups.map((g) => (
              <button
                key={g.name}
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  handleAddGroupToDay(day.dateStr, g);
                }}
                className="w-full text-left px-1.5 py-1 rounded hover:bg-emerald-500/10 text-white/80 hover:text-emerald-400 text-[9px] font-bold transition-all border-none bg-transparent cursor-pointer flex items-center justify-between"
              >
                <span>👥 {g.name}</span>
                <span className="text-[7.5px] text-white/35 font-bold">{g.memberIds.length} crew</span>
              </button>
            ))}
            {crewGroups.length === 0 && (
              <div className="text-[8px] text-white/30 italic px-1.5 py-1">No saved groups</div>
            )}
          </div>
        )}
      </button>
    </div>
  </>
) : (
  <div className="flex flex-col gap-1.5 h-full min-h-[80px]">
    <div
      onClick={(e) => {
        e.stopPropagation();
        handleCellClick(day.dateStr, 'openshifts', 'SERVER');
      }}
      className="flex-1 py-2 flex flex-col items-center justify-center border border-dashed border-emerald-500/40 hover:border-emerald-400 bg-emerald-500/[0.03] hover:bg-emerald-500/[0.08] rounded-md transition-all cursor-pointer text-[10px] font-black uppercase text-emerald-400/80 hover:text-emerald-400 gap-1 select-none border-solid"
    >
      <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
      <span>ADD</span>
    </div>

    <div
      data-group-popover-cell={day.dateStr}
      onClick={(e) => {
        e.stopPropagation();
        setCellGroupPopover(prev => prev === day.dateStr ? null : day.dateStr);
      }}
      className="flex-1 py-2 flex flex-col items-center justify-center border border-dashed border-emerald-500/40 hover:border-emerald-400 bg-emerald-500/[0.03] hover:bg-emerald-500/[0.08] rounded-md transition-all cursor-pointer text-[10px] font-black uppercase text-emerald-400/80 hover:text-emerald-400 gap-1 select-none relative border-solid"
    >
      <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
      <span>ADD GROUP</span>

      {cellGroupPopover === day.dateStr && (
        <div 
          className="absolute top-full left-0 right-0 mt-1 bg-[#18181b] border border-white/10 rounded-lg shadow-xl z-30 p-1.5 flex flex-col gap-1 min-w-[130px]"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="text-[8px] font-extrabold text-white/40 uppercase tracking-widest px-2 py-1 border-b border-white/5">Select Saved Group</div>
          {crewGroups.map((g) => (
            <button
              key={g.name}
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                handleAddGroupToDay(day.dateStr, g);
              }}
              className="w-full text-left px-2 py-1.5 rounded hover:bg-emerald-500/10 text-white/80 hover:text-emerald-400 text-[9.5px] font-bold transition-all border-none bg-transparent cursor-pointer flex items-center justify-between"
            >
              <span>👥 {g.name}</span>
              <span className="text-[7.5px] text-white/35 font-bold">{g.memberIds.length} crew</span>
            </button>
          ))}
          {crewGroups.length === 0 && (
            <div className="text-[8.5px] text-white/30 italic px-2 py-1.5">No saved groups</div>
          )}
        </div>
      )}
    </div>
  </div>
)}

